@page "/settings"
@rendermode InteractiveServer
@using sv_89f7958c151a445fa4cc1644da1e9918.Services
@inject ISettingsService SettingsService

<PageTitle>Settings</PageTitle>

<div class="settings-dashboard">
    <nav class="settings-sidebar">
        <h5 class="sidebar-title">Settings</h5>
        @foreach (var section in _sections)
        {
            <button class="sidebar-item @(section == _activeSection ? "active" : "")"
                    @onclick="() => SetActiveSection(section)">
                <span class="sidebar-icon">@GetSectionIcon(section)</span>
                @section
            </button>
        }
    </nav>

    <div class="settings-content">
        @if (_loading)
        {
            <div class="loading-spinner">
                <div class="spinner-border text-primary" role="status">
                    <span class="visually-hidden">Loading...</span>
                </div>
            </div>
        }
        else
        {
            @switch (_activeSection)
            {
                case "Profile":
                    @RenderProfileSection()
                    break;
                case "Notifications":
                    @RenderNotificationsSection()
                    break;
                case "Security":
                    @RenderSecuritySection()
                    break;
                case "Appearance":
                    @RenderAppearanceSection()
                    break;
            }
        }

        @if (_toastVisible)
        {
            <div class="toast-notification @(_toastIsError ? "toast-error" : "toast-success")">
                @_toastMessage
            </div>
        }
    </div>
</div>

@* ───── Profile Section ───── *@
@{
    RenderFragment RenderProfileSection() =>
        @<div class="section-panel">
            <h3>Profile</h3>
            <p class="section-description">Manage your public profile information.</p>

            <div class="avatar-area">
                <img src="@_profileAvatarUrl" alt="Avatar" class="avatar-preview" />
                <span class="avatar-url-label">@_profileAvatarUrl</span>
            </div>

            <div class="form-group">
                <label for="displayName">Display Name</label>
                <input id="displayName" class="form-control" @bind="_profileDisplayName" />
            </div>
            <div class="form-group">
                <label for="email">Email</label>
                <input id="email" type="email" class="form-control" @bind="_profileEmail" />
            </div>
            <div class="form-group">
                <label for="bio">Bio</label>
                <textarea id="bio" class="form-control" rows="4" @bind="_profileBio"></textarea>
            </div>

            <div class="button-row">
                <button class="btn btn-primary" @onclick="SaveProfile">Save Changes</button>
                <button class="btn btn-outline-secondary" @onclick="DiscardProfileChanges">Discard Changes</button>
            </div>
        </div>;
}

@* ───── Notifications Section ───── *@
@{
    RenderFragment RenderNotificationsSection() =>
        @<div class="section-panel">
            <h3>Notifications</h3>
            <p class="section-description">Control how and when you receive notifications.</p>

            <div class="toggle-row">
                <label class="toggle-label">Email Notifications</label>
                <label class="switch">
                    <input type="checkbox" checked="@_notifEmail" @onchange="e => _notifEmail = (bool)e.Value!" />
                    <span class="slider"></span>
                </label>
            </div>
            <div class="toggle-row">
                <label class="toggle-label">Push Notifications</label>
                <label class="switch">
                    <input type="checkbox" checked="@_notifPush" @onchange="e => _notifPush = (bool)e.Value!" />
                    <span class="slider"></span>
                </label>
            </div>
            <div class="toggle-row">
                <label class="toggle-label">Weekly Digest</label>
                <label class="switch">
                    <input type="checkbox" checked="@_notifDigest" @onchange="e => _notifDigest = (bool)e.Value!" />
                    <span class="slider"></span>
                </label>
            </div>

            <h5 class="sub-heading">Muted Channels</h5>
            <div class="channel-list">
                @foreach (var channel in _allChannels)
                {
                    var isMuted = _mutedChannels.Contains(channel);
                    <label class="channel-item">
                        <input type="checkbox" checked="@isMuted"
                               @onchange="e => ToggleMutedChannel(channel, (bool)e.Value!)" />
                        <span>#@channel</span>
                    </label>
                }
            </div>

            <div class="button-row">
                <button class="btn btn-primary" @onclick="SaveNotifications">Save Preferences</button>
            </div>
        </div>;
}

@* ───── Security Section ───── *@
@{
    RenderFragment RenderSecuritySection() =>
        @<div class="section-panel">
            <h3>Security</h3>
            <p class="section-description">Manage passwords, two-factor authentication, and active sessions.</p>

            <div class="expandable-panel">
                <button class="expandable-header" @onclick="() => _passwordPanelOpen = !_passwordPanelOpen">
                    <span>Change Password</span>
                    <span class="chevron @(_passwordPanelOpen ? "open" : "")">▸</span>
                </button>
                @if (_passwordPanelOpen)
                {
                    <div class="expandable-body">
                        <div class="form-group">
                            <label for="currentPwd">Current Password</label>
                            <input id="currentPwd" type="password" class="form-control" @bind="_currentPassword" />
                        </div>
                        <div class="form-group">
                            <label for="newPwd">New Password</label>
                            <input id="newPwd" type="password" class="form-control" @bind="_newPassword" />
                        </div>
                        <div class="form-group">
                            <label for="confirmPwd">Confirm Password</label>
                            <input id="confirmPwd" type="password" class="form-control" @bind="_confirmPassword" />
                        </div>
                        @if (!string.IsNullOrEmpty(_passwordError))
                        {
                            <div class="validation-error">@_passwordError</div>
                        }
                        <button class="btn btn-primary" @onclick="UpdatePassword">Update Password</button>
                    </div>
                }
            </div>

            <div class="toggle-row">
                <div>
                    <label class="toggle-label">Two-Factor Authentication</label>
                    <span class="status-badge @(_twoFactorEnabled ? "status-on" : "status-off")">
                        @(_twoFactorEnabled ? "Enabled" : "Disabled")
                    </span>
                </div>
                <label class="switch">
                    <input type="checkbox" checked="@_twoFactorEnabled"
                           @onchange="e => _twoFactorEnabled = (bool)e.Value!" />
                    <span class="slider"></span>
                </label>
            </div>

            @if (_securityLastPasswordChange.HasValue)
            {
                <p class="muted-text">Last password change: @_securityLastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
            }

            <h5 class="sub-heading">Active Sessions</h5>
            <div class="table-responsive">
                <table class="table session-table">
                    <thead>
                        <tr>
                            <th>Device</th>
                            <th>Location</th>
                            <th>Last Active</th>
                            <th></th>
                        </tr>
                    </thead>
                    <tbody>
                        @foreach (var session in _sessions)
                        {
                            var isCurrentSession = session == _sessions.FirstOrDefault();
                            <tr>
                                <td>@session.Device</td>
                                <td>@session.Location</td>
                                <td>@FormatLastActive(session.LastActive)</td>
                                <td>
                                    @if (isCurrentSession)
                                    {
                                        <span class="current-badge">Current</span>
                                    }
                                    else
                                    {
                                        <button class="btn btn-sm btn-outline-danger"
                                                @onclick="() => PromptRevokeSession(session)">
                                            Revoke
                                        </button>
                                    }
                                </td>
                            </tr>
                        }
                    </tbody>
                </table>
            </div>

            @if (_showRevokeConfirm && _sessionToRevoke is not null)
            {
                <div class="modal-backdrop" @onclick="CancelRevoke">
                    <div class="confirm-dialog" @onclick:stopPropagation="true">
                        <h5>Revoke Session</h5>
                        <p>Are you sure you want to revoke the session on <strong>@_sessionToRevoke.Device</strong> from <strong>@_sessionToRevoke.Location</strong>?</p>
                        <div class="button-row">
                            <button class="btn btn-danger" @onclick="ConfirmRevokeSession">Revoke</button>
                            <button class="btn btn-outline-secondary" @onclick="CancelRevoke">Cancel</button>
                        </div>
                    </div>
                </div>
            }
        </div>;
}

@* ───── Appearance Section ───── *@
@{
    RenderFragment RenderAppearanceSection() =>
        @<div class="section-panel">
            <h3>Appearance</h3>
            <p class="section-description">Customize how the application looks and feels.</p>

            <h5 class="sub-heading">Theme</h5>
            <div class="radio-group">
                @foreach (var theme in new[] { "Light", "Dark", "System" })
                {
                    <label class="radio-item">
                        <input type="radio" name="theme" value="@theme"
                               checked="@(_appearanceTheme == theme)"
                               @onchange="() => _appearanceTheme = theme" />
                        <span>@theme</span>
                    </label>
                }
            </div>

            <h5 class="sub-heading">Font Size</h5>
            <div class="radio-group">
                @foreach (var size in new[] { "Small", "Medium", "Large" })
                {
                    <label class="radio-item">
                        <input type="radio" name="fontSize" value="@size"
                               checked="@(_appearanceFontSize == size)"
                               @onchange="() => _appearanceFontSize = size" />
                        <span>@size</span>
                    </label>
                }
            </div>

            <div class="form-group">
                <label for="language">Language</label>
                <select id="language" class="form-select" @bind="_appearanceLanguage">
                    <option value="English">English</option>
                    <option value="Spanish">Spanish</option>
                    <option value="French">French</option>
                    <option value="German">German</option>
                    <option value="Japanese">Japanese</option>
                    <option value="Portuguese">Portuguese</option>
                </select>
            </div>

            <div class="toggle-row">
                <label class="toggle-label">Compact Mode</label>
                <label class="switch">
                    <input type="checkbox" checked="@_appearanceCompact"
                           @onchange="e => _appearanceCompact = (bool)e.Value!" />
                    <span class="slider"></span>
                </label>
            </div>

            <h5 class="sub-heading">Live Preview</h5>
            <div class="live-preview @GetPreviewClasses()">
                <div class="preview-header">Settings Dashboard</div>
                <div class="preview-body">
                    <p>This is a preview of your selected appearance settings.</p>
                    <div class="preview-card">
                        <span class="preview-label">Theme:</span> @_appearanceTheme &nbsp;
                        <span class="preview-label">Font:</span> @_appearanceFontSize &nbsp;
                        <span class="preview-label">Language:</span> @_appearanceLanguage
                    </div>
                    <button class="preview-btn">Sample Button</button>
                </div>
            </div>

            <div class="button-row">
                <button class="btn btn-primary" @onclick="SaveAppearance">Save</button>
            </div>
        </div>;
}

@code {
    // Section navigation
    private readonly string[] _sections = ["Profile", "Notifications", "Security", "Appearance"];
    private string _activeSection = "Profile";
    private bool _loading = true;

    // Toast
    private bool _toastVisible;
    private string _toastMessage = "";
    private bool _toastIsError;

    // Profile state
    private string _profileDisplayName = "";
    private string _profileEmail = "";
    private string _profileAvatarUrl = "";
    private string _profileBio = "";
    private UserProfile? _savedProfile;

    // Notifications state
    private bool _notifEmail;
    private bool _notifPush;
    private bool _notifDigest;
    private List<string> _mutedChannels = [];
    private readonly List<string> _allChannels = ["general", "announcements", "random", "engineering", "design", "support"];

    // Security state
    private bool _passwordPanelOpen;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private string _passwordError = "";
    private bool _twoFactorEnabled;
    private DateTime? _securityLastPasswordChange;
    private List<ActiveSession> _sessions = [];
    private bool _showRevokeConfirm;
    private ActiveSession? _sessionToRevoke;

    // Appearance state
    private string _appearanceTheme = "Light";
    private string _appearanceFontSize = "Medium";
    private string _appearanceLanguage = "English";
    private bool _appearanceCompact;

    protected override async Task OnInitializedAsync()
    {
        await LoadSectionData(_activeSection);
        _loading = false;
    }

    private async Task SetActiveSection(string section)
    {
        if (section == _activeSection) return;
        _activeSection = section;
        _loading = true;
        await LoadSectionData(section);
        _loading = false;
    }

    private async Task LoadSectionData(string section)
    {
        switch (section)
        {
            case "Profile":
                var profile = await SettingsService.GetProfileAsync();
                _savedProfile = profile;
                ApplyProfile(profile);
                break;
            case "Notifications":
                var prefs = await SettingsService.GetNotificationPrefsAsync();
                _notifEmail = prefs.EmailNotifications;
                _notifPush = prefs.PushNotifications;
                _notifDigest = prefs.WeeklyDigest;
                _mutedChannels = new List<string>(prefs.MutedChannels);
                break;
            case "Security":
                var sec = await SettingsService.GetSecuritySettingsAsync();
                _twoFactorEnabled = sec.TwoFactorEnabled;
                _securityLastPasswordChange = sec.LastPasswordChange;
                _sessions = new List<ActiveSession>(sec.Sessions);
                _passwordPanelOpen = false;
                _currentPassword = "";
                _newPassword = "";
                _confirmPassword = "";
                _passwordError = "";
                _showRevokeConfirm = false;
                _sessionToRevoke = null;
                break;
            case "Appearance":
                var app = await SettingsService.GetAppearanceAsync();
                _appearanceTheme = app.Theme;
                _appearanceFontSize = app.FontSize;
                _appearanceLanguage = app.Language;
                _appearanceCompact = app.CompactMode;
                break;
        }
    }

    private void ApplyProfile(UserProfile profile)
    {
        _profileDisplayName = profile.DisplayName;
        _profileEmail = profile.Email;
        _profileAvatarUrl = profile.AvatarUrl;
        _profileBio = profile.Bio;
    }

    // ── Profile actions ──

    private async Task SaveProfile()
    {
        var updated = new UserProfile(_profileDisplayName, _profileEmail, _profileAvatarUrl, _profileBio);
        await SettingsService.SaveProfileAsync(updated);
        _savedProfile = updated;
        await ShowToast("Profile saved successfully.");
    }

    private async Task DiscardProfileChanges()
    {
        if (_savedProfile is not null)
            ApplyProfile(_savedProfile);
        await ShowToast("Changes discarded.");
    }

    // ── Notifications actions ──

    private void ToggleMutedChannel(string channel, bool muted)
    {
        if (muted && !_mutedChannels.Contains(channel))
            _mutedChannels.Add(channel);
        else if (!muted)
            _mutedChannels.Remove(channel);
    }

    private async Task SaveNotifications()
    {
        var prefs = new NotificationPrefs(_notifEmail, _notifPush, _notifDigest, new List<string>(_mutedChannels));
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        await ShowToast("Notification preferences saved.");
    }

    // ── Security actions ──

    private async Task UpdatePassword()
    {
        _passwordError = "";
        if (string.IsNullOrWhiteSpace(_currentPassword))
        {
            _passwordError = "Current password is required.";
            return;
        }
        if (_newPassword.Length < 8)
        {
            _passwordError = "New password must be at least 8 characters.";
            return;
        }
        if (_newPassword != _confirmPassword)
        {
            _passwordError = "Passwords do not match.";
            return;
        }
        await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
        _currentPassword = "";
        _newPassword = "";
        _confirmPassword = "";
        await ShowToast("Password updated successfully.");
    }

    private void PromptRevokeSession(ActiveSession session)
    {
        _sessionToRevoke = session;
        _showRevokeConfirm = true;
    }

    private async Task ConfirmRevokeSession()
    {
        if (_sessionToRevoke is not null)
        {
            await SettingsService.RevokeSessionAsync(_sessionToRevoke.Id);
            _sessions.RemoveAll(s => s.Id == _sessionToRevoke.Id);
        }
        _showRevokeConfirm = false;
        _sessionToRevoke = null;
        await ShowToast("Session revoked.");
    }

    private void CancelRevoke()
    {
        _showRevokeConfirm = false;
        _sessionToRevoke = null;
    }

    // ── Appearance actions ──

    private string GetPreviewClasses()
    {
        var classes = new List<string>();
        classes.Add(_appearanceTheme.ToLowerInvariant() switch
        {
            "dark" => "preview-dark",
            "system" => "preview-system",
            _ => "preview-light"
        });
        classes.Add(_appearanceFontSize.ToLowerInvariant() switch
        {
            "small" => "preview-font-small",
            "large" => "preview-font-large",
            _ => "preview-font-medium"
        });
        if (_appearanceCompact) classes.Add("preview-compact");
        return string.Join(" ", classes);
    }

    private async Task SaveAppearance()
    {
        var settings = new AppearanceSettings(_appearanceTheme, _appearanceFontSize, _appearanceLanguage, _appearanceCompact);
        await SettingsService.SaveAppearanceAsync(settings);
        await ShowToast("Appearance settings saved.");
    }

    // ── Helpers ──

    private static string GetSectionIcon(string section) => section switch
    {
        "Profile" => "👤",
        "Notifications" => "🔔",
        "Security" => "🔒",
        "Appearance" => "🎨",
        _ => "⚙️"
    };

    private static string FormatLastActive(DateTime dt)
    {
        var diff = DateTime.UtcNow - dt;
        if (diff.TotalMinutes < 1) return "Just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes}m ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
        return $"{(int)diff.TotalDays}d ago";
    }

    private async Task ShowToast(string message, bool isError = false)
    {
        _toastMessage = message;
        _toastIsError = isError;
        _toastVisible = true;
        StateHasChanged();
        await Task.Delay(3000);
        _toastVisible = false;
        StateHasChanged();
    }
