@page "/settings"
@rendermode InteractiveServer
@using sv_89f7958c151a445fa4cc1644da1e9918.Services
@inject ISettingsService SettingsService

<PageTitle>Settings</PageTitle>

<div class="settings-dashboard">
    <nav class="settings-sidebar">
        <h5 class="sidebar-title">Settings</h5>
        @foreach (var section in _sections)
        {
            <button class="sidebar-item @(section == _activeSection ? "active" : "")"
                    @onclick="() => SetActiveSection(section)">
                <span class="sidebar-icon">@GetSectionIcon(section)</span>
                @section
            </button>
        }
    </nav>

    <div class="settings-content">
        @if (_loading)
        {
            <div class="loading-spinner">
                <div class="spinner-border text-primary" role="status">
                    <span class="visually-hidden">Loading...</span>
                </div>
            </div>
        }
        else
        {
            @switch (_activeSection)
            {
                case "Profile":
                    @RenderProfileSection()
                    break;
                case "Notifications":
                    @RenderNotificationsSection()
                    break;
                case "Security":
                    @RenderSecuritySection()
                    break;
                case "Appearance":
                    @RenderAppearanceSection()
                    break;
            }
        }

        @if (_toastVisible)
        {
            <div class="toast-notification @(_toastIsError ? "toast-error" : "toast-success")">
                @_toastMessage
            </div>
        }
    </div>
</div>

@* ───── Profile Section ───── *@
@{
    RenderFragment RenderProfileSection() =>
        @<div class="section-panel">
            <h3>Profile</h3>
            <p class="section-description">Manage your public profile information.</p>

            <div class="avatar-area">
                <img src="@_profileAvatarUrl" alt="Avatar" class="avatar-preview" />
                <span class="avatar-url-label">@_profileAvatarUrl</span>
            </div>

            <div class="form-group">
                <label for="displayName">Display Name</label>
                <input id="displayName" class="form-control" @bind="_profileDisplayName" />
            </div>
            <div class="form-group">
                <label for="email">Email</label>
                <input id="email" type="email" class="form-control" @bind="_profileEmail" />
            </div>
            <div class="form-group">
                <label for="bio">Bio</label>
                <textarea id="bio" class="form-control" rows="4" @bind="_profileBio"></textarea>
            </div>

            <div class="button-row">
                <button class="btn btn-primary" @onclick="SaveProfile">Save Changes</button>
                <button class="btn btn-outline-secondary" @onclick="DiscardProfileChanges">Discard Changes</button>
            </div>
        </div>;
}

@* ───── Notifications Section ───── *@
@{
    RenderFragment RenderNotificationsSection() =>
        @<div class="section-panel">
            <h3>Notifications</h3>
            <p class="section-description">Control how and when you receive notifications.</p>

            <div class="toggle-row">
                <label class="toggle-label">Email Notifications</label>
                <label class="switch">
                    <input type="checkbox" checked="@_notifEmail" @onchange="e => _notifEmail = (bool)e.Value!" />
                    <span class="slider"></span>
                </label>
            </div>
            <div class="toggle-row">
                <label class="toggle-label">Push Notifications</label>
                <label class="switch">
                    <input type="checkbox" checked="@_notifPush" @onchange="e => _notifPush = (bool)e.Value!" />
                    <span class="slider"></span>
                </label>
            </div>
            <div class="toggle-row">
                <label class="toggle-label">Weekly Digest</label>
                <label class="switch">
                    <input type="checkbox" checked="@_notifDigest" @onchange="e => _notifDigest = (bool)e.Value!" />
                    <span class="slider"></span>
                </label>
            </div>

            <h5 class="sub-heading">Muted Channels</h5>
            <div class="channel-list">
                @foreach (var channel in _allChannels)
                {
                    var isMuted = _mutedChannels.Contains(channel);
                    <label class="channel-item">
                        <input type="checkbox" checked="@isMuted"
                               @onchange="e => ToggleMutedChannel(channel, (bool)e.Value!)" />
                        <span>#@channel</span>
                    </label>
                }
            </div>

            <div class="button-row">
                <button class="btn btn-primary" @onclick="SaveNotifications">Save Preferences</button>
            </div>
        </div>;
}

@* ───── Security Section ───── *@
@{
    RenderFragment RenderSecuritySection() =>
        @<div class="section-panel">
            <h3>Security</h3>
            <p class="section-description">Manage passwords, two-factor authentication, and active sessions.</p>

            <div class="expandable-panel">
                <button class="expandable-header" @onclick="() => _passwordPanelOpen = !_passwordPanelOpen">
                    <span>Change Password</span>
                    <span class="chevron @(_passwordPanelOpen ? "open" : "")">▸</span>
                </button>
                @if (_passwordPanelOpen)
                {
                    <div class="expandable-body">
                        <div class="form-group">
                            <label for="currentPwd">Current Password</label>
                            <input id="currentPwd" type="password" class="form-control" @bind="_currentPassword" />
                        </div>
                        <div class="form-group">
                            <label for="newPwd">New Password</label>
                            <input id="newPwd" type="password" class="form-control" @bind="_newPassword" />
                        </div>
                        <div class="form-group">
                            <label for="confirmPwd">Confirm Password</label>
                            <input id="confirmPwd" type="password" class="form-control" @bind="_confirmPassword" />
                        </div>
                        @if (!string.IsNullOrEmpty(_passwordError))
                        {
                            <div class="validation-error">@_passwordError</div>
                        }
                        <button class="btn btn-primary" @onclick="UpdatePassword">Update Password</button>
                    </div>
                }
            </div>

            <div class="toggle-row">
                <div>
                    <label class="toggle-label">Two-Factor Authentication</label>
                    <span class="status-badge @(_twoFactorEnabled ? "status-on" : "status-off")">
                        @(_twoFactorEnabled ? "Enabled" : "Disabled")
                    </span>
                </div>
                <label class="switch">
                    <input type="checkbox" checked="@_twoFactorEnabled"
                           @onchange="e => _twoFactorEnabled = (bool)e.Value!" />
                    <span class="slider"></span>
                </label>
            </div>

            @if (_securityLastPasswordChange.HasValue)
            {
                <p class="muted-text">Last password change: @_securityLastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
            }

            <h5 class="sub-heading">Active Sessions</h5>
            <div class="table-responsive">
                <table class="table session-table">
                    <thead>
                        <tr>
                            <th>Device</th>
                            <th>Location</th>
                            <th>Last Active</th>
                            <th></th>
                        </tr>
                    </thead>
                    <tbody>
                        @foreach (var session in _sessions)
                        {
                            var isCurrentSession = session == _sessions.FirstOrDefault();
                            <tr>
                                <td>@session.Device</td>
                                <td>@session.Location</td>
                                <td>@FormatLastActive(session.LastActive)</td>
                                <td>
                                    @if (isCurrentSession)
                                    {
                                        <span class="current-badge">Current</span>
                                    }
                                    else
                                    {
                                        <button class="btn btn-sm btn-outline-danger"
                                                @onclick="() => PromptRevokeSession(session)">
                                            Revoke
                                        </button>
                                    }
                                </td>
                            </tr>
                        }
                    </tbody>
                </table>
            </div>

            @if (_showRevokeConfirm && _sessionToRevoke is not null)
            {
                <div class="modal-backdrop" @onclick="CancelRevoke">
                    <div class="confirm-dialog" @onclick:stopPropagation="true">
                        <h5>Revoke Session</h5>
                        <p>Are you sure you want to revoke the session on <strong>@_sessionToRevoke.Device</strong> from <strong>@_sessionToRevoke.Location</strong>?</p>
                        <div class="button-row">
                            <button class="btn btn-danger" @onclick="ConfirmRevokeSession">Revoke</button>
                            <button class="btn btn-outline-secondary" @onclick="CancelRevoke">Cancel</button>
                        </div>
                    </div>
                </div>
            }
        </div>;
}

@* ───── Appearance Section ───── *@
@{
    RenderFragment RenderAppearanceSection() =>
        @<div class="section-panel">
            <h3>Appearance</h3>
            <p class="section-description">Customize how the application looks and feels.</p>

            <h5 class="sub-heading">Theme</h5>
            <div class="radio-group">
                @foreach (var theme in new[] { "Light", "Dark", "System" })
                {
                    <label class="radio-item">
                        <input type="radio" name="theme" value="@theme"
                               checked="@(_appearanceTheme == theme)"
                               @onchange="() => _appearanceTheme = theme" />
                        <span>@theme</span>
                    </label>
                }
            </div>

            <h5 class="sub-heading">Font Size</h5>
            <div class="radio-group">
                @foreach (var size in new[] { "Small", "Medium", "Large" })
                {
                    <label class="radio-item">
                        <input type="radio" name="fontSize" value="@size"
                               checked="@(_appearanceFontSize == size)"
                               @onchange="() => _appearanceFontSize = size" />
                        <span>@size</span>
                    </label>
                }
            </div>

            <div class="form-group">
                <label for="language">Language</label>
                <select id="language" class="form-select" @bind="_appearanceLanguage">
                    <option value="English">English</option>
                    <option value="Spanish">Spanish</option>
                    <option value="French">French</option>
                    <option value="German">German</option>
                    <option value="Japanese">Japanese</option>
                    <option value="Portuguese">Portuguese</option>
                </select>
            </div>

            <div class="toggle-row">
                <label class="toggle-label">Compact Mode</label>
                <label class="switch">
                    <input type="checkbox" checked="@_appearanceCompact"
                           @onchange="e => _appearanceCompact = (bool)e.Value!" />
                    <span class="slider"></span>
                </label>
            </div>

            <h5 class="sub-heading">Live Preview</h5>
            <div class="live-preview @GetPreviewClasses()">
                <div class="preview-header">Settings Dashboard</div>
                <div class="preview-body">
                    <p>This is a preview of your selected appearance settings.</p>
                    <div class="preview-card">
                        <span class="preview-label">Theme:</span> @_appearanceTheme &nbsp;
                        <span class="preview-label">Font:</span> @_appearanceFontSize &nbsp;
                        <span class="preview-label">Language:</span> @_appearanceLanguage
                    </div>
                    <button class="preview-btn">Sample Button</button>
                </div>
            </div>

            <div class="button-row">
                <button class="btn btn-primary" @onclick="SaveAppearance">Save</button>
            </div>
        </div>;
}

