@code {
    // Section navigation
    private readonly string[] _sections = ["Profile", "Notifications", "Security", "Appearance"];
    private string _activeSection = "Profile";
    private bool _loading = true;

    // Toast
    private bool _toastVisible;
    private string _toastMessage = "";
    private bool _toastIsError;

    // Profile state
    private string _profileDisplayName = "";
    private string _profileEmail = "";
    private string _profileAvatarUrl = "";
    private string _profileBio = "";
    private UserProfile? _savedProfile;

    // Notifications state
    private bool _notifEmail;
    private bool _notifPush;
    private bool _notifDigest;
    private List<string> _mutedChannels = [];
    private readonly List<string> _allChannels = ["general", "announcements", "random", "engineering", "design", "support"];

    // Security state
    private bool _passwordPanelOpen;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private string _passwordError = "";
    private bool _twoFactorEnabled;
    private DateTime? _securityLastPasswordChange;
    private List<ActiveSession> _sessions = [];
    private bool _showRevokeConfirm;
    private ActiveSession? _sessionToRevoke;

    // Appearance state
    private string _appearanceTheme = "Light";
    private string _appearanceFontSize = "Medium";
    private string _appearanceLanguage = "English";
    private bool _appearanceCompact;

    protected override async Task OnInitializedAsync()
    {
        await LoadSectionData(_activeSection);
        _loading = false;
    }

    private async Task SetActiveSection(string section)
    {
        if (section == _activeSection) return;
        _activeSection = section;
        _loading = true;
        await LoadSectionData(section);
        _loading = false;
    }

    private async Task LoadSectionData(string section)
    {
        switch (section)
        {
            case "Profile":
                var profile = await SettingsService.GetProfileAsync();
                _savedProfile = profile;
                ApplyProfile(profile);
                break;
            case "Notifications":
                var prefs = await SettingsService.GetNotificationPrefsAsync();
                _notifEmail = prefs.EmailNotifications;
                _notifPush = prefs.PushNotifications;
                _notifDigest = prefs.WeeklyDigest;
                _mutedChannels = new List<string>(prefs.MutedChannels);
                break;
            case "Security":
                var sec = await SettingsService.GetSecuritySettingsAsync();
                _twoFactorEnabled = sec.TwoFactorEnabled;
                _securityLastPasswordChange = sec.LastPasswordChange;
                _sessions = new List<ActiveSession>(sec.Sessions);
                _passwordPanelOpen = false;
                _currentPassword = "";
                _newPassword = "";
                _confirmPassword = "";
                _passwordError = "";
                _showRevokeConfirm = false;
                _sessionToRevoke = null;
                break;
            case "Appearance":
                var app = await SettingsService.GetAppearanceAsync();
                _appearanceTheme = app.Theme;
                _appearanceFontSize = app.FontSize;
                _appearanceLanguage = app.Language;
                _appearanceCompact = app.CompactMode;
                break;
        }
    }

    private void ApplyProfile(UserProfile profile)
    {
        _profileDisplayName = profile.DisplayName;
        _profileEmail = profile.Email;
        _profileAvatarUrl = profile.AvatarUrl;
        _profileBio = profile.Bio;
    }

    // ── Profile actions ──

    private async Task SaveProfile()
    {
        var updated = new UserProfile(_profileDisplayName, _profileEmail, _profileAvatarUrl, _profileBio);
        await SettingsService.SaveProfileAsync(updated);
        _savedProfile = updated;
        await ShowToast("Profile saved successfully.");
    }

    private async Task DiscardProfileChanges()
    {
        if (_savedProfile is not null)
            ApplyProfile(_savedProfile);
        await ShowToast("Changes discarded.");
    }

    // ── Notifications actions ──

    private void ToggleMutedChannel(string channel, bool muted)
    {
        if (muted && !_mutedChannels.Contains(channel))
            _mutedChannels.Add(channel);
        else if (!muted)
            _mutedChannels.Remove(channel);
    }

    private async Task SaveNotifications()
    {
        var prefs = new NotificationPrefs(_notifEmail, _notifPush, _notifDigest, new List<string>(_mutedChannels));
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        await ShowToast("Notification preferences saved.");
    }

    // ── Security actions ──

    private async Task UpdatePassword()
    {
        _passwordError = "";
        if (string.IsNullOrWhiteSpace(_currentPassword))
        {
            _passwordError = "Current password is required.";
            return;
        }
        if (_newPassword.Length < 8)
        {
            _passwordError = "New password must be at least 8 characters.";
            return;
        }
        if (_newPassword != _confirmPassword)
        {
            _passwordError = "Passwords do not match.";
            return;
        }
        await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
        _currentPassword = "";
        _newPassword = "";
        _confirmPassword = "";
        await ShowToast("Password updated successfully.");
    }

    private void PromptRevokeSession(ActiveSession session)
    {
        _sessionToRevoke = session;
        _showRevokeConfirm = true;
    }

    private async Task ConfirmRevokeSession()
    {
        if (_sessionToRevoke is not null)
        {
            await SettingsService.RevokeSessionAsync(_sessionToRevoke.Id);
            _sessions.RemoveAll(s => s.Id == _sessionToRevoke.Id);
        }
        _showRevokeConfirm = false;
        _sessionToRevoke = null;
        await ShowToast("Session revoked.");
    }

    private void CancelRevoke()
    {
        _showRevokeConfirm = false;
        _sessionToRevoke = null;
    }

    // ── Appearance actions ──

    private string GetPreviewClasses()
    {
        var classes = new List<string>();
        classes.Add(_appearanceTheme.ToLowerInvariant() switch
        {
            "dark" => "preview-dark",
            "system" => "preview-system",
            _ => "preview-light"
        });
        classes.Add(_appearanceFontSize.ToLowerInvariant() switch
        {
            "small" => "preview-font-small",
            "large" => "preview-font-large",
            _ => "preview-font-medium"
        });
        if (_appearanceCompact) classes.Add("preview-compact");
        return string.Join(" ", classes);
    }

    private async Task SaveAppearance()
    {
        var settings = new AppearanceSettings(_appearanceTheme, _appearanceFontSize, _appearanceLanguage, _appearanceCompact);
        await SettingsService.SaveAppearanceAsync(settings);
        await ShowToast("Appearance settings saved.");
    }

    // ── Helpers ──

    private static string GetSectionIcon(string section) => section switch
    {
        "Profile" => "👤",
        "Notifications" => "🔔",
        "Security" => "🔒",
        "Appearance" => "🎨",
        _ => "⚙️"
    };

    private static string FormatLastActive(DateTime dt)
    {
        var diff = DateTime.UtcNow - dt;
        if (diff.TotalMinutes < 1) return "Just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes}m ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
        return $"{(int)diff.TotalDays}d ago";
    }

    private async Task ShowToast(string message, bool isError = false)
    {
        _toastMessage = message;
        _toastIsError = isError;
        _toastVisible = true;
        StateHasChanged();
        await Task.Delay(3000);
        _toastVisible = false;
        StateHasChanged();
    }
}

